const JAVA_PARTITIONS = `public class Solution{public String[][] partition(String s){java.util.ArrayList<String[]>o=new java.util.ArrayList<>();go(s,0,new java.util.ArrayList<String>(),o);return o.toArray(new String[0][]);}void go(String s,int i,java.util.ArrayList<String>p,java.util.ArrayList<String[]>o){if(i==s.length()){o.add(p.toArray(new String[0]));return;}for(int j=i+1;j<=s.length();j++){String x=s.substring(i,j);String r=new StringBuilder(x).reverse().toString();if(!x.equals(r))continue;p.add(x);go(s,j,p,o);p.remove(p.size()-1);}}}`;
const JAVA_QUEENS = `public class Solution{public String[][] solveNQueens(int n){java.util.ArrayList<String[]>o=new java.util.ArrayList<>();go(0,n,new int[n],new boolean[n],new boolean[2*n],new boolean[2*n],o);return o.toArray(new String[0][]);}void go(int r,int n,int[]q,boolean[]c,boolean[]a,boolean[]b,java.util.ArrayList<String[]>o){if(r==n){String[]z=new String[n];for(int i=0;i<n;i++){char[]x=new char[n];java.util.Arrays.fill(x,'.');x[q[i]]='Q';z[i]=new String(x);}o.add(z);return;}for(int j=0;j<n;j++)if(!c[j]&&!a[r+j]&&!b[r-j+n]){q[r]=j;c[j]=a[r+j]=b[r-j+n]=true;go(r+1,n,q,c,a,b,o);c[j]=a[r+j]=b[r-j+n]=false;}}}`;
const JAVA_MERGE_INTERVALS = `public class Solution{public int[][] mergeIntervals(int[][]a){java.util.Arrays.sort(a,(x,y)->Integer.compare(x[0],y[0]));java.util.ArrayList<int[]>o=new java.util.ArrayList<>();for(int[]x:a){if(o.isEmpty()||o.get(o.size()-1)[1]<x[0])o.add(new int[]{x[0],x[1]});else o.get(o.size()-1)[1]=Math.max(o.get(o.size()-1)[1],x[1]);}return o.toArray(new int[0][]);}}`;
